{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, a para-substituted benzamide with a basic diethylaminoethyl side chain, has an absolute oral bioavailability of 75% after oral vs IV dosing in normal volunteers, supporting high F for the query benzamide analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "N-acetylprocainamide, the acetylated analogue of procainamide, has an absolute bioavailability of 87.2% (range 79.2-93.0%) measured by stable-isotope IV/oral administration, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Sematilide, another para-substituted benzamide with a basic ethylamine side chain, has an absolute oral bioavailability of about 58-59%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Haloperidol, a 4-chlorophenyl-containing drug, has an absolute oral bioavailability of 0.64 ± 0.23 in humans; despite lower structural similarity, it supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Indoramin, a benzamide with a piperidine side chain, had a median absolute oral bioavailability of only 7.7% in film-coated tablets, below the 20% threshold; however, its extensive first-pass metabolism and different side chain limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small 4-chlorobenzamide with a morpholinoethyl side chain. The closest experimental analogues—procainamide, N-acetylprocainamide, and sematilide—are para-substituted benzamides with basic aminoethyl side chains and show absolute oral bioavailability of 46-87%, all above the 20% threshold. The low-F examples (indoramin, loperamide) are structurally more distant and their low F is driven by extensive first-pass metabolism or P-gp efflux not expected for this small morpholine benzamide. Therefore predict high F (>=20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself.",
    "No fed-state-specific bioavailability data in the retrieved evidence; extrapolation from non-specified or fasted studies is required.",
    "Morgan similarities are low (0.28-0.34), so transferability relies on chemical class analogy rather than close structural identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

